import React, { useState } from "react";
import { TextField, Button, Box, Select, MenuItem, Paper, Typography, IconButton } from "@mui/material";
import { AddCircleOutline, RemoveCircleOutline } from "@mui/icons-material";
import axios from "axios";

const ContactForm = () => {
  const [fields, setFields] = useState([
    { id: "1", Type: "input", value: [""], label: "Name" },
  ]);

  // Handle input changes
  const handleChange = (index, key, newValue) => {
    const updatedFields = [...fields];
    updatedFields[index][key] = key === "value" ? [newValue] : newValue;
    setFields(updatedFields);
  };

  // Add a new field
  const addField = () => {
    const newField = { id: `${fields.length + 1}`, Type: "input", value: [""], label: "" };
    setFields([...fields, newField]);
  };

  // Remove a field
  const removeField = (index) => {
    const updatedFields = fields.filter((_, i) => i !== index);
    setFields(updatedFields);
  };

  // Submit form
  const handleSubmit = async () => {
    try {
      const response = await axios.post("http://localhost:5000/contact-form", fields);
      console.log("Form submitted:", response.data);
    } catch (error) {
      console.error("Error submitting form:", error);
    }
  };

  return (
    <Paper sx={{ p: 3, width: "100%", maxWidth: 500, mx: "auto" }} className="Edit">
      <Typography variant="h6" gutterBottom>
        Dynamic Contact Form
      </Typography>

      {fields.map((field, index) => (
        <Box key={index} display="flex" alignItems="center" gap={2} mb={2} flexDirection='column'>
          {/* Field Type Selection */}
          <Select
            value={field.Type}
            onChange={(e) => handleChange(index, "Type", e.target.value)}
            sx={{ minWidth: 120 }}
          >
            <MenuItem value="input">Input</MenuItem>
            <MenuItem value="textarea">Textarea</MenuItem>
            <MenuItem value="select">Dropdown</MenuItem>
          </Select>

          {/* Field Label */}
          <TextField
            fullWidth
            label="Label"
            variant="outlined"
            value={field.label}
            onChange={(e) => handleChange(index, "label", e.target.value)}
          />

          {/* Field Value */}
          <TextField
            label="Value"
            variant="outlined"
            value={field.value[0]}
            onChange={(e) => handleChange(index, "value", e.target.value)}
          />

          {/* Remove Field Button */}
          <IconButton onClick={() => removeField(index)} color="error">
            <RemoveCircleOutline />
          </IconButton>
        </Box>
      ))}

      {/* Add Field Button */}
      <Button onClick={addField} startIcon={<AddCircleOutline />} variant="outlined">
        Add Field
      </Button>

      {/* Submit Button */}
      <Button onClick={handleSubmit} variant="contained" color="primary" sx={{ mt: 2, ml: 2 }}>
        Submit
      </Button>
    </Paper>
  );
};

export default ContactForm;
